#[cfg(unix)]
#[test]
#[ignore = "explicit release bundle metadata growth diagnostic"]
fn profile_bundle_metadata_growth() {
    use crate::bundle::BundleReader;
    use crate::column_artifact::BUNDLE_PATH;
    use std::os::unix::fs::MetadataExt;
    for (chunk_rows, calls) in [(1, 1024), (120, 128), (15_360, 64)] {
        let temp = TempDir::new().unwrap();
        let config = NativeStorageConfig { data_dir: temp.path().to_owned(), hot_target_rows: 1_000_000, ..Default::default() };
        let mut storage = NativeStorage::open(config.clone()).unwrap();
        let mut elapsed = std::time::Duration::ZERO;
        let mut expected = Vec::new();
        for call in 1..=calls {
            let header = ingestion_header(1_000_000 - call as u64, B256::ZERO);
            let rows = ingestion_rows(chunk_rows, &header);
            let start = std::time::Instant::now();
            storage.ingest_historical_batch(&rows, &header).unwrap();
            elapsed += start.elapsed();
            expected.extend(rows);
            if [1, 16, 64, 128, 256, 512, 1024].contains(&call) {
                let mut artifact_bytes = 0u64;
                let mut allocated_bytes = 0u64;
                let mut live_bytes = 0u64;
                let mut bundles = 0u64;
                for segment in storage.segments() {
                    if let Some(reference) = &segment.column_bundle {
                        let path = storage.segment_path(segment.id).join(BUNDLE_PATH);
                        let stat = fs::metadata(&path).unwrap();
                        artifact_bytes += stat.len();
                        allocated_bytes += stat.blocks() * 512;
                        let reader = BundleReader::open(&path, reference).unwrap();
                        live_bytes += u64::from(reference.chain_bytes) + 8;
                        for stream in (0..14).chain(28..=crate::column_artifact::CANONICAL_STREAM) {
                            live_bytes += reader.stream_len(stream).unwrap();
                        }
                        bundles += 1;
                    }
                }
                println!("{}", serde_json::json!({"kind":"bundle_growth", "chunk_rows":chunk_rows, "calls":call, "rows":expected.len(), "ingest_ms":elapsed.as_secs_f64()*1000.0, "bundles":bundles, "artifact_bytes":artifact_bytes, "allocated_bytes":allocated_bytes, "live_artifact_bytes":live_bytes, "stale_metadata_bytes":artifact_bytes-live_bytes}));
            }
        }
        let start = std::time::Instant::now();
        storage.finalize_active_historical_segment().unwrap();
        storage.checkpoint().unwrap();
        let finalization = start.elapsed();
        expected.sort_by_key(|row| (row.block_number, row.log_index));
        assert_eq!(read_ingestion_rows(&storage), expected);
        drop(storage);
        let start = std::time::Instant::now();
        let reopened = NativeStorage::open(config).unwrap();
        let reopen = start.elapsed();
        assert_eq!(read_ingestion_rows(&reopened), expected);
        println!("{}", serde_json::json!({"kind":"bundle_growth_complete", "chunk_rows":chunk_rows, "calls":calls, "rows":expected.len(), "ingest_ms":elapsed.as_secs_f64()*1000.0, "finalization_ms":finalization.as_secs_f64()*1000.0, "reopen_ms":reopen.as_secs_f64()*1000.0, "exact_oracles":true}));
    }
}
